def solution(s):
    res = []
    def is_pal(sub):
        return sub == sub[::-1]
    def backtrack(start, path):
        if start == len(s):
            res.append(list(path))
            return
        for end in range(start + 1, len(s) + 1):
            prefix = s[start:end]
            if is_pal(prefix):
                path.append(prefix)
                backtrack(end, path)
                path.pop()
    backtrack(0, [])
    return res
